import{_ as t,o as a,c as n,ah as o}from"./chunks/framework.C-FRNfAJ.js";const p=JSON.parse('{"title":"Payments","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/apprenant/paiements.md","filePath":"src/en/guide/apprenant/paiements.md"}'),r={name:"en/guide/apprenant/paiements.md"};function i(s,e,d,h,c,l){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="payments" tabindex="-1">Payments <a class="header-anchor" href="#payments" aria-label="Permalink to &quot;Payments&quot;">​</a></h1><p>The price of the training is paid in <strong>three instalments</strong>, set by your agreement. You follow invoices and due dates in <strong>Journeys → My enrolment</strong>, under &quot;Invoices&quot;.</p><h2 id="the-30-40-30-schedule" tabindex="-1">The 30 / 40 / 30 schedule <a class="header-anchor" href="#the-30-40-30-schedule" aria-label="Permalink to &quot;The 30 / 40 / 30 schedule&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Instalment</th><th>Share of the price</th><th>Due date</th></tr></thead><tbody><tr><td>Signature</td><td>30%</td><td>At the start of the cohort, or at signing if later</td></tr><tr><td>Mid-point</td><td>40%</td><td>In the middle of the cohort</td></tr><tr><td>Balance</td><td>30%</td><td>At the end of the cohort</td></tr></tbody></table><p>The exact dates are in your agreement. Amounts are <strong>excluding tax</strong>: the invoice carries the exemption mention and the payment details.</p><h2 id="invoices" tabindex="-1">Invoices <a class="header-anchor" href="#invoices" aria-label="Permalink to &quot;Invoices&quot;">​</a></h2><p>Each instalment gives an invoice (reference <code>FAC-NB-YYYY-XXX</code>), sent as a PDF by e-mail and available in <strong>My documents</strong>:</p><ul><li>the first is issued at the <strong>counter-signature</strong> of your agreement;</li><li>the next two are issued <strong>15 days before</strong> their due date.</li></ul><p>If a company funds you in part, each instalment is invoiced in <strong>two separate invoices</strong>: yours for your share, theirs for theirs. Each is followed separately.</p><h2 id="how-to-pay" tabindex="-1">How to pay <a class="header-anchor" href="#how-to-pay" aria-label="Permalink to &quot;How to pay&quot;">​</a></h2><p>Payments are <strong>received outside Kura</strong>, then recorded by the Pedagogical Coordinator with the amount, method, reference and date. You can pay by bank transfer, cheque, Mobile Money (Flooz, T-Money), card or cash. The precise payment details are on each invoice.</p><p>A <strong>partial</strong> payment is possible; the recorded amount can never exceed what is due. For each payment recorded, you receive an acknowledgement.</p><h2 id="reminders" tabindex="-1">Reminders <a class="header-anchor" href="#reminders" aria-label="Permalink to &quot;Reminders&quot;">​</a></h2><p>Kura warns you before and after each due date, by e-mail, and also in Sève and on WhatsApp if your account is open and your phone entered:</p><ul><li><strong>15, 7 and 1 days before</strong> the due date;</li><li><strong>the day after</strong> the due date, if the instalment is unpaid.</li></ul><h2 id="if-an-instalment-is-not-paid" tabindex="-1">If an instalment is not paid <a class="header-anchor" href="#if-an-instalment-is-not-paid" aria-label="Permalink to &quot;If an instalment is not paid&quot;">​</a></h2><p>The timeline is the same for every instalment:</p><table tabindex="0"><thead><tr><th>When</th><th>What happens</th></tr></thead><tbody><tr><td>Due date</td><td>The instalment must be paid</td></tr><tr><td>D+1</td><td>Automatic reminder</td></tr><tr><td>D+7</td><td>The Coordinator contacts you (e-mail or phone)</td></tr><tr><td>D+15</td><td>The invoice becomes &quot;Overdue&quot;. A <strong>15-day moratorium</strong> starts, automatic and unique. You are notified</td></tr><tr><td>D+30</td><td>Without payment, your <strong>access to Sève is suspended</strong>. You are notified</td></tr><tr><td>After D+30</td><td>Interview with the Coordinator, possible repayment plan; unenrolment if there is no settlement</td></tr></tbody></table><p><strong>Paying, at any moment, restores your access automatically.</strong> The suspension only concerns Sève: your documents and your Kura file remain accessible.</p><p>If the <strong>funder</strong> is late, your access is suspended too, even if your own share is paid.</p><h2 id="if-your-situation-changes" tabindex="-1">If your situation changes <a class="header-anchor" href="#if-your-situation-changes" aria-label="Permalink to &quot;If your situation changes&quot;">​</a></h2><ul><li><strong>Postponement or force majeure.</strong> You change cohort: what you have paid is kept. What remained due on invoices already issued is cancelled by a <strong>credit note</strong> (<code>AV-NB-YYYY-XXX</code>), and the new agreement re-invoices each instalment, deducting what you have already paid.</li><li><strong>Cohort cancelled by NextBoxx</strong> before it starts: Kura issues a credit note for a <strong>100% refund</strong> of the sums paid. The Coordinator records the refund once it is made.</li><li><strong>Drop-out.</strong> No credit note: instalments not yet invoiced will no longer be, but invoices already issued remain due. You receive a partial attestation for the validated blocks (see <a href="./certification.html#if-you-drop-out">Certificate and Canopé</a>).</li></ul><h2 id="the-balance-conditions-the-certificate" tabindex="-1">The balance conditions the certificate <a class="header-anchor" href="#the-balance-conditions-the-certificate" aria-label="Permalink to &quot;The balance conditions the certificate&quot;">​</a></h2><p>The <strong>balance paid in full</strong> is one of the four conditions of the certificate (see <a href="./certification.html">Certificate and Canopé</a>).</p>',24)])])}const m=t(r,[["render",i]]);export{p as __pageData,m as default};
